<script setup>
import { RemoveFilled } from "@element-plus/icons-vue";

const props = defineProps([ 'filterData','removeFilter','id', 'columns']);
const emit = defineEmits(['update:filterData']);

const operatorOptions = [
        {
            value: '=', label: 'Equal', operator: '='
        },
        {
            value: '!=', label: 'Not Equal', operator: '!='
        },
        {
            value: 'LIKE', label: 'Contain', operator: 'LIKE'
        },
        {
            value: 'NOT LIKE', label: 'Not Contain', operator: 'NOT LIKE'
        }
];

const updateField = (field, value) => {
    emit('update:filterData', { ...props.filterData, [field]: value });
};
</script>

<template>
    <div class="fv-form-row fv-gap-1">

        <el-select :modelValue="props.filterData.filter" @update:modelValue="updateField('filter', $event)" placeholder="Select">
            <el-option
            v-for="item in columns"
            :key="item.colKey"
            :label="item.alias"
            :value="item.colKey"
            />
        </el-select>
        <el-select :modelValue="props.filterData.operator" @update:modelValue="updateField('operator', $event)" placeholder="Select">
            <el-option
            v-for="item in operatorOptions"
            :key="item.value"
            :label="item.label"
            :value="item.value"
            />
        </el-select>
        <el-input class="wml-filter-value" placeholder="Enter Value" :modelValue="props.filterData.value" @update:modelValue="updateField('value', $event)" />
        <el-icon v-if="id != 0" class="el-icon--left fv-remove-condition" @click="(e) => removeFilter(e,props.id)" :id="props.id"><RemoveFilled /></el-icon>
    </div>
</template>
